"""Hand-written V-Slice compat scripts (no AI needed) for common Psych events."""

_HELPERS = """
  function num(s:String, d:Float):Float
  {
    if (s == null || s == '') return d;
    var f:Float = Std.parseFloat(s);
    return Math.isNaN(f) ? d : f;
  }
"""

_HEAD = """import funkin.play.event.SongEvent;
import funkin.data.event.SongEventSchema;
import funkin.data.event.SongEventSchema.SongEventFieldType;
import funkin.play.PlayState;
import flixel.FlxG;
"""

ADD_CAMERA_ZOOM = _HEAD + """
// Auto-generated by FNFVSlice-Converter: Psych "Add Camera Zoom" compatibility event.
class AddCameraZoomEvent extends SongEvent
{
  public function new() { super('AddCameraZoom'); }
""" + _HELPERS + """
  public override function handleEvent(data:SongEventData):Void
  {
    if (PlayState.instance == null || PlayState.instance.isMinimalMode) return;
    FlxG.camera.zoom += num(data.getString('value1'), 0.015);
    PlayState.instance.camHUD.zoom += num(data.getString('value2'), 0.03);
  }

  public override function getEventSchema():SongEventSchema
  {
    return new SongEventSchema([
      {name: 'value1', title: 'Game zoom', defaultValue: '0.015', type: SongEventFieldType.STRING},
      {name: 'value2', title: 'HUD zoom', defaultValue: '0.03', type: SongEventFieldType.STRING}
    ]);
  }

  public override function getTitle():String { return 'Add Camera Zoom'; }
}
"""

SCREEN_SHAKE = _HEAD + """
// Auto-generated by FNFVSlice-Converter: Psych "Screen Shake" compatibility event.
// Psych format: value1 = "duration, intensity" (game), value2 = "duration, intensity" (HUD).
class ScreenShakeEvent extends SongEvent
{
  public function new() { super('ScreenShake'); }
""" + _HELPERS + """
  function shake(cam:Dynamic, raw:String):Void
  {
    if (raw == null || raw == '') return;
    var p:Array<String> = raw.split(',');
    var dur:Float = num(p[0], 0);
    var inten:Float = num(p.length > 1 ? p[1] : '', 0);
    if (dur > 0 && inten > 0) cam.shake(inten, dur);
  }

  public override function handleEvent(data:SongEventData):Void
  {
    if (PlayState.instance == null || PlayState.instance.isMinimalMode) return;
    shake(FlxG.camera, data.getString('value1'));
    shake(PlayState.instance.camHUD, data.getString('value2'));
  }

  public override function getEventSchema():SongEventSchema
  {
    return new SongEventSchema([
      {name: 'value1', title: 'Game (dur, intensity)', defaultValue: '0.5, 0.05', type: SongEventFieldType.STRING},
      {name: 'value2', title: 'HUD (dur, intensity)', defaultValue: '', type: SongEventFieldType.STRING}
    ]);
  }

  public override function getTitle():String { return 'Screen Shake'; }
}
"""

COMPAT = {"AddCameraZoom": ADD_CAMERA_ZOOM, "ScreenShake": SCREEN_SHAKE}
